public class IntersectionOfTwoLinkedLists {
    static class ListNode {
        int val;
        ListNode next;
        ListNode(int v) { val = v; }
    }

    public ListNode getIntersectionNode(ListNode headA, ListNode headB) {
        if (headA == null || headB == null) return null;
        ListNode pa = headA, pb = headB;
        while (pa != pb) {                          // 交点或同时为 null 时退出
            pa = (pa == null) ? headB : pa.next;    // 走到末尾就切换到对方头部
            pb = (pb == null) ? headA : pb.next;
        }
        return pa;                                  // 交点节点或 null
    }
}

// --- 替代解法：先求长度差，长链表先走差值步 ---
public ListNode getIntersectionNodeByLengthDiff(ListNode headA, ListNode headB) {
    int lenA = length(headA), lenB = length(headB);
    ListNode longer  = lenA >= lenB ? headA : headB;
    ListNode shorter = lenA >= lenB ? headB : headA;
    int diff = Math.abs(lenA - lenB);
    for (int i = 0; i < diff; i++) longer = longer.next;  // 长链表先走 diff 步
    while (longer != shorter) {                           // 同步走直到相遇
        longer  = longer.next;
        shorter = shorter.next;
    }
    return longer;
}

private int length(ListNode head) {
    int n = 0;
    for (ListNode p = head; p != null; p = p.next) n++;
    return n;
}
